const input=$json;
const cases=Array.isArray(input.cases)?input.cases:[];

function stable(value){
  if(value===null || typeof value!=='object') return JSON.stringify(value);
  if(Array.isArray(value)) return '['+value.map(stable).join(',')+']';
  return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+stable(value[k])).join(',')+'}';
}
function equal(a,b){ return stable(a)===stable(b); }
function subset(expected,actual){
  if(expected===null || typeof expected!=='object') return equal(expected,actual);
  if(Array.isArray(expected)) return equal(expected,actual);
  if(actual===null || typeof actual!=='object') return false;
  return Object.keys(expected).every((key)=>subset(expected[key],actual[key]));
}
function pushCheck(checks,name,pass,details=null){
  checks.push({name,pass:Boolean(pass),details});
}
function answerChecks(expected,response,checks){
  const c=expected ?? {};
  const text=response===null || response===undefined ? '' : String(response);
  if(Object.prototype.hasOwnProperty.call(c,'response_required')){
    pushCheck(checks,'response_required',c.response_required ? text.length>0 : text.length===0,{length:text.length});
  }
  if(Array.isArray(c.must_include)){
    for(const value of c.must_include) pushCheck(checks,'must_include:'+value,text.includes(String(value)));
  }
  if(Array.isArray(c.must_not_include)){
    for(const value of c.must_not_include) pushCheck(checks,'must_not_include:'+value,!text.includes(String(value)));
  }
  if(Number.isFinite(Number(c.max_chars))){
    pushCheck(checks,'max_chars',text.length<=Number(c.max_chars),{actual:text.length,max:Number(c.max_chars)});
  }
  if(Object.prototype.hasOwnProperty.call(c,'exact_response')){
    pushCheck(checks,'exact_response',text===String(c.exact_response));
  }
  if(c.forbid_internal_tier===true){
    pushCheck(checks,'forbid_internal_tier',!/\bT\d{3,5}\b/i.test(text));
  }
}

const evaluations=[];
for(const entry of cases){
  const fixture=entry?.fixture ?? {};
  const candidate=entry?.candidate ?? {};
  const expected=fixture.expected_ref ?? entry?.expected_ref ?? null;
  const checks=[];

  const effects=Array.isArray(candidate.side_effects)?candidate.side_effects:[];
  pushCheck(checks,'zero_side_effects',effects.length===0,{count:effects.length});

  if(expected){
    if(Object.prototype.hasOwnProperty.call(expected,'action')){
      pushCheck(checks,'action_match',equal(expected.action,candidate.action ?? null),{
        expected:expected.action,actual:candidate.action ?? null
      });
    }
    if(Object.prototype.hasOwnProperty.call(expected,'state')){
      pushCheck(checks,'state_match',subset(expected.state,candidate.state ?? null),{
        expected:expected.state,actual:candidate.state ?? null
      });
    }
    if(Object.prototype.hasOwnProperty.call(expected,'guard')){
      pushCheck(checks,'guard_match',subset(expected.guard,candidate.guard ?? null),{
        expected:expected.guard,actual:candidate.guard ?? null
      });
    }
    answerChecks(expected.answer_constraints,candidate.response,checks);
  }

  const failed=checks.filter(c=>!c.pass);
  let verdict='not_evaluated';
  if(expected){
    verdict=failed.length?'fail':(expected.review_required===true?'review':'pass');
  }else if(effects.length>0){
    verdict='fail';
  }

  const metrics={
    checks_total:checks.length,
    checks_passed:checks.filter(c=>c.pass).length,
    checks_failed:failed.length,
    side_effect_count:effects.length,
    pass_rate:checks.length ? checks.filter(c=>c.pass).length/checks.length : null
  };

  evaluations.push({
    fixture_id:fixture.id ?? entry?.fixture_id ?? null,
    input_event_id:fixture.input_event_id ?? null,
    customer_event_id:fixture.customer_event_id ?? null,
    correlation_id:fixture.correlation_id ?? null,
    verdict,
    checks,
    metrics,
    candidate_action:candidate.action ?? {},
    candidate_response:candidate.response ?? null,
    expected_ref:expected,
    context_snapshot:fixture.context_snapshot ?? {},
    side_effects:effects
  });
}

const summary={pass:0,fail:0,review:0,not_evaluated:0,total:evaluations.length};
for(const e of evaluations) summary[e.verdict]=(summary[e.verdict]??0)+1;

const operations=evaluations.map((e)=>({
  action:'RECORD_SHADOW_EVALUATION',
  input_event_id:e.input_event_id,
  customer_event_id:e.customer_event_id,
  correlation_id:e.correlation_id,
  candidate_action:e.candidate_action,
  candidate_response:e.candidate_response,
  expected_ref:e.expected_ref,
  verdict:e.verdict,
  metrics:e.metrics,
  context_snapshot:e.context_snapshot
}));

return {json:{
  status:summary.fail>0?'fail':summary.review>0?'review':'pass',
  replay_run_id:input.replay_run_id ?? null,
  summary,
  evaluations,
  operations,
  side_effects_executed:false,
  blockers:[]
}};
